import java.io.*;
import java.util.*;

public class F {
    void solve() {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        try {
            int n = Integer.parseInt(br.readLine());
            char[] s = br.readLine().toCharArray();
            int[] a = Arrays.stream(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();

            int[] f = new int[26];
            for (char c : s) f[c - 'a']++;
            boolean ok = true;
            for (int i = 0; i < 26; i++) {
                if (f[i] > n / 2) {
                    System.out.println(-1);
                    ok = false;
                    break;
                }
            }
            if (!ok) return;

            for (int i = 0; i < n / 2; i++) {
                if (a[i] > a[n - 1 - i]) {
                    int tmp = a[i]; a[i] = a[n - 1 - i]; a[n - 1 - i] = tmp;
                    char tmpc = s[i]; s[i] = s[n - 1 - i]; s[n - 1 - i] = tmpc;
                }
            }

            List<Edge> es = new ArrayList<>();
            int src = n, sink = n + 1;
            for (int i = 0; i < n / 2; i++) {
                es.add(new Edge(src, i, 1, 0));
                es.add(new Edge(n - 1 - i, sink, 1, 0));
                for (int j = 0; j < n / 2; j++) {
                    if (s[i] != s[n - 1 - j]) {
                        es.add(new Edge(i, n - 1 - j, 1, i == j ? 0 : a[i]));
                    }
                }
            }

            long ans = Arrays.stream(a).asLongStream().sum();
            System.out.println(ans - solveMinCostFlow(compileWD(sink + 1, es), src, sink, n));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static class Edge {
        int from, to, capacity, cost, flow;
        Edge complement;
        Edge(int from, int to, int capacity, int cost) {
            this.from = from; this.to = to; this.capacity = capacity; this.cost = cost;
        }
    }

    static Edge[][] compileWD(int n, List<Edge> edges) {
        Edge[][] g = new Edge[n][];
        for (int i = edges.size() - 1; i >= 0; i--) {
            Edge origin = edges.get(i);
            Edge clone = new Edge(origin.to, origin.from, origin.capacity, -origin.cost);
            clone.flow = origin.capacity;
            clone.complement = origin;
            origin.complement = clone;
            edges.add(clone);
        }
        int[] p = new int[n];
        for (Edge e : edges) p[e.from]++;
        for (int i = 0; i < n; i++) g[i] = new Edge[p[i]];
        for (Edge e : edges) g[e.from][--p[e.from]] = e;
        return g;
    }

    static long solveMinCostFlow(Edge[][] g, int source, int sink, long all) {
        int n = g.length;
        long mincost = 0;
        int[] potential = new int[n];
        int[] d = new int[n];
        Edge[] inedge = new Edge[n];
        while (all > 0) {
            Arrays.fill(d, Integer.MAX_VALUE / 2);
            Arrays.fill(inedge, null);
            d[source] = 0;
            PriorityQueue<Integer> pq = new PriorityQueue<>(Comparator.comparingInt(i -> d[i]));
            pq.add(source);
            while (!pq.isEmpty()) {
                int cur = pq.poll();
                if (d[cur] == Integer.MAX_VALUE / 2) continue;
                for (Edge ne : g[cur]) {
                    if (ne.capacity - ne.flow > 0) {
                        int nd = d[cur] + ne.cost + potential[cur] - potential[ne.to];
                        if (d[ne.to] > nd) {
                            d[ne.to] = nd;
                            inedge[ne.to] = ne;
                            pq.add(ne.to);
                        }
                    }
                }
            }
            if (inedge[sink] == null) break;
            long minflow = all;
            long sumcost = 0;
            for (Edge e = inedge[sink]; e != null; e = inedge[e.from]) {
                if (e.capacity - e.flow < minflow) minflow = e.capacity - e.flow;
                sumcost += e.cost;
            }
            mincost += minflow * sumcost;
            for (Edge e = inedge[sink]; e != null; e = inedge[e.from]) {
                e.flow += minflow;
                e.complement.flow -= minflow;
            }
            all -= minflow;
            for (int i = 0; i < n; i++) {
                potential[i] += d[i];
            }
        }
        return mincost;
    }

    public static void main(String[] args) {
        new F().solve();
    }
}
